void WireStatuses(ShapeAnalysis_Wire& analyzer,WireDiagnostic& output) {
 for(int s=0;s<=18;++s){auto status=static_cast<ShapeExtend_Status>(s);
  output.status.push_back(analyzer.StatusOrder(status));output.status.push_back(analyzer.StatusConnected(status));
  output.status.push_back(analyzer.StatusSmall(status));output.status.push_back(analyzer.StatusEdgeCurves(status));
  output.status.push_back(analyzer.StatusDegenerated(status));output.status.push_back(analyzer.StatusSelfIntersection(status));
  output.status.push_back(analyzer.StatusLacking(status));output.status.push_back(analyzer.StatusClosed(status));}
}
